.btn { min-height: 42px; padding: 0 18px; border: 0; border-radius: var(--radius-md); font: 800 14px/1 'Coupang Sans', Pretendard, sans-serif; display: inline-flex; align-items: center; justify-content: center; gap: 8px; transition: transform var(--duration-fast) var(--ease-out), background var(--duration-fast) var(--ease-out), opacity var(--duration-fast) linear; cursor: pointer; }
